// Writes the companion app's shared code from the website's own sources.
//
//   pnpm companion:sync            write apps/companion/src/generated/
//   pnpm companion:sync --check    exit 1, naming each stale file, and write nothing
//
// The app is a standalone Expo project rather than a workspace package
// (docs/COMPANION_APP.md), so it cannot import from the website. What it needs
// from it is generated instead, from tracked files only, and
// `tests/companion/sync.test.ts` fails whenever a generated file no longer
// matches what this would write. Never from `payload-types.ts`: it is
// gitignored, absent in CI's `checks` job, and new code here stays off it.
//
// What is generated:
//
//   - `block-slugs.ts`, from `BLOCK_SLUGS` in `blocks/schema.ts`. The app's
//     renderer is typed against it, so a block added to the website is a type
//     error in the app until somebody decides how it renders there.
//   - `brand-tokens.ts`, from the two top-level `:root` blocks of
//     `app/globals.css`. Colours only, as literal hex: `var()` and
//     `color-mix(in srgb, …)` are resolved here, because React Native has
//     neither. Everything else in those blocks — the font stacks built on
//     next/font variables, the plate gradient, layout lengths — is omitted and
//     named in the file, so an omission is visible rather than silent.

import { mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { pathToFileURL } from 'node:url'

import { BLOCK_SLUGS } from '../blocks/schema'

/** Where the generated files live, relative to the repository root. */
export const GENERATED_DIR = 'apps/companion/src/generated'

export type GeneratedFile = { path: string; contents: string }

const header = (source: string): string =>
  [
    `// GENERATED by \`pnpm companion:sync\` from ${source}. Do not edit.`,
    '// tests/companion/sync.test.ts fails when this file is out of date.',
    '',
  ].join('\n')

export function renderBlockSlugs(slugs: readonly string[]): string {
  return [
    header('`BLOCK_SLUGS` in blocks/schema.ts'),
    '/** Every block an article body can contain, in the website’s order. */',
    'export const BLOCK_SLUGS = [',
    ...slugs.map((slug) => `  ${JSON.stringify(slug)},`),
    '] as const',
    '',
    'export type BlockSlug = (typeof BLOCK_SLUGS)[number]',
    '',
  ].join('\n')
}

// --- Brand tokens --------------------------------------------------------

/**
 * The custom properties declared in each top-level `:root` block, in order.
 *
 * Top-level only: the `:root` inside a media query overrides the masthead
 * height for phones, a layout value the app has no use for. Comments are
 * dropped before declarations are split, since several contain semicolons.
 */
export function readRootProperties(css: string): Map<string, string> {
  const properties = new Map<string, string>()
  const withoutComments = css.replace(/\/\*[\s\S]*?\*\//g, '')

  for (const block of withoutComments.matchAll(/^:root\s*\{([\s\S]*?)^\}/gm)) {
    for (const declaration of block[1]!.split(';')) {
      const match = /^\s*(--[\w-]+)\s*:\s*([\s\S]+?)\s*$/.exec(declaration)
      if (match) properties.set(match[1]!, match[2]!.replace(/\s+/g, ' '))
    }
  }
  return properties
}

type Rgb = [number, number, number]

function hexToRgb(hex: string): Rgb | null {
  const match = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(hex.trim())
  if (!match) return null
  const digits =
    match[1]!.length === 3
      ? [...match[1]!].map((digit) => digit + digit).join('')
      : match[1]!
  return [0, 2, 4].map((at) =>
    Number.parseInt(digits.slice(at, at + 2), 16),
  ) as Rgb
}

const rgbToHex = (rgb: Rgb): string =>
  `#${rgb.map((channel) => channel.toString(16).padStart(2, '0')).join('')}`

/** Splits on commas that are not inside parentheses. */
function splitArguments(value: string): string[] {
  const parts: string[] = []
  let depth = 0
  let current = ''
  for (const char of value) {
    if (char === '(') depth += 1
    if (char === ')') depth -= 1
    if (char === ',' && depth === 0) {
      parts.push(current.trim())
      current = ''
    } else {
      current += char
    }
  }
  parts.push(current.trim())
  return parts
}

/**
 * A colour value reduced to a literal `#rrggbb`, or null when it is not one.
 *
 * Understands hex, `var()` of another custom property in the same blocks, and
 * `color-mix(in srgb, A p%, B q%)` between two opaque colours, mixed per CSS
 * Color 5: a missing percentage is the remainder of the other, and the mix is
 * a per-channel weighted average in sRGB, rounded to the nearest byte. A mix
 * whose percentages sum below 100 has alpha, which `#rrggbb` cannot hold, so it
 * is null rather than approximated.
 */
export function resolveColour(
  value: string,
  properties: ReadonlyMap<string, string>,
  seen: ReadonlySet<string> = new Set(),
): string | null {
  const trimmed = value.trim()

  const variable = /^var\(\s*(--[\w-]+)\s*\)$/.exec(trimmed)
  if (variable) {
    const name = variable[1]!
    const target = properties.get(name)
    if (target === undefined || seen.has(name)) return null
    return resolveColour(target, properties, new Set([...seen, name]))
  }

  const rgb = hexToRgb(trimmed)
  if (rgb) return rgbToHex(rgb)

  const mix = /^color-mix\(\s*in\s+srgb\s*,([\s\S]*)\)$/i.exec(trimmed)
  if (!mix) return null

  const operands = splitArguments(mix[1]!).map((operand) => {
    const percent = /\s+(\d+(?:\.\d+)?)%$/.exec(operand)
    return {
      colour: percent ? operand.slice(0, percent.index) : operand,
      percent: percent ? Number(percent[1]) : null,
    }
  })
  if (operands.length !== 2) return null

  const [first, second] = operands as [
    (typeof operands)[number],
    (typeof operands)[number],
  ]
  const p1 =
    first.percent ?? (second.percent === null ? 50 : 100 - second.percent)
  const p2 = second.percent ?? 100 - p1
  if (p1 < 0 || p2 < 0 || p1 + p2 < 100) return null

  const a = hexToRgb(resolveColour(first.colour, properties, seen) ?? '')
  const b = hexToRgb(resolveColour(second.colour, properties, seen) ?? '')
  if (!a || !b) return null

  const total = p1 + p2
  return rgbToHex(
    a.map((channel, index) =>
      Math.round((channel * p1 + b[index]! * p2) / total),
    ) as Rgb,
  )
}

const camel = (name: string): string =>
  name.replace(/-([a-z0-9])/g, (_, char: string) => char.toUpperCase())

/** Why a non-colour custom property was left out, for the file's own record. */
function omissionReason(name: string, value: string): string {
  if (name.startsWith('--font-')) {
    return 'a font stack built on a next/font variable; the app loads Playfair Display and Inter with expo-font'
  }
  if (/gradient\(/.test(value)) {
    return 'a CSS gradient, not a colour; the app builds the same wash from the colours above'
  }
  if (/^-?[\d.]+(px|rem|em|vw|vh)$/.test(value)) {
    return 'a CSS length for the website layout'
  }
  return 'not a colour'
}

export function renderBrandTokens(css: string): string {
  const properties = readRootProperties(css)
  const brand: Array<[string, string, string]> = []
  const pigments: Array<[string, string, string]> = []
  const omitted: Array<[string, string]> = []

  for (const [name, value] of properties) {
    const colour = resolveColour(value, properties)
    if (!colour) {
      omitted.push([name, omissionReason(name, value)])
      continue
    }
    if (name.startsWith('--pig-')) {
      pigments.push([camel(name.slice('--pig-'.length)), colour, value])
    } else {
      brand.push([camel(name.replace(/^--(color-)?/, '')), colour, value])
    }
  }

  const entries = (rows: Array<[string, string, string]>) =>
    rows.flatMap(([key, colour, source]) => [
      ...(source.toLowerCase() === colour ? [] : [`  /** ${source} */`]),
      `  ${key}: '${colour}',`,
    ])

  return [
    header('the top-level `:root` blocks of app/globals.css'),
    '/** The paper, ink and burgundy palette: the website’s `--color-*`. */',
    'export const BRAND_COLORS = {',
    ...entries(brand),
    '} as const',
    '',
    '/** The pigment colours: the website’s `--pig-*`. */',
    'export const PIGMENT_COLORS = {',
    ...entries(pigments),
    '} as const',
    '',
    '/** Custom properties in those blocks that are not colours, and why each is left out. */',
    'export const OMITTED_TOKENS = {',
    ...omitted.map(
      ([name, reason]) =>
        `  ${JSON.stringify(name)}: ${JSON.stringify(reason)},`,
    ),
    '} as const',
    '',
  ].join('\n')
}

/** Every generated file, as it should be, from the sources under `root`. */
export function renderCompanionFiles(root: string): GeneratedFile[] {
  return [
    {
      path: `${GENERATED_DIR}/block-slugs.ts`,
      contents: renderBlockSlugs(BLOCK_SLUGS),
    },
    {
      path: `${GENERATED_DIR}/brand-tokens.ts`,
      contents: renderBrandTokens(
        readFileSync(join(root, 'app/globals.css'), 'utf8'),
      ),
    },
  ]
}

function readOrNull(path: string): string | null {
  try {
    return readFileSync(path, 'utf8')
  } catch {
    return null
  }
}

function main(argv: string[]): void {
  const root = resolve(dirname(new URL(import.meta.url).pathname), '..')
  const check = argv.includes('--check')
  const stale: string[] = []

  for (const file of renderCompanionFiles(root)) {
    const target = join(root, file.path)
    if (readOrNull(target) === file.contents) continue
    stale.push(file.path)
    if (!check) {
      mkdirSync(dirname(target), { recursive: true })
      writeFileSync(target, file.contents)
    }
  }

  if (check && stale.length > 0) {
    console.error(
      `Out of date — run \`pnpm companion:sync\`:\n  ${stale.join('\n  ')}`,
    )
    process.exit(1)
  }
  console.log(
    check
      ? 'The companion app’s generated files are current.'
      : stale.length > 0
        ? `Wrote ${stale.join(', ')}`
        : 'Nothing to write; every generated file is current.',
  )
}

if (
  process.argv[1] &&
  import.meta.url === pathToFileURL(resolve(process.argv[1])).href
) {
  main(process.argv.slice(2))
}
